  async function api(path,body){const opts=body===undefined?{credentials:'same-origin'}:{method:'POST',headers:{'Content-Type':'application/json'},credentials:'same-origin',body:JSON.stringify(body)};const r=await fetch((cfg.apiBase||'api')+'/'+path,opts);let j={};try{j=await r.json()}catch(_){throw new Error('The store returned an invalid response.')}if(!r.ok||j.ok===false){const e=new Error(j.message||j.errors?.join(' ')||j.error||'Store request failed.');e.payload=j;throw e}return j}
  async function loadPlans(){try{const j=await api('plans.php');st.plans=j.plans||[];return st.plans}catch(_){st.plans=[];return []}}
  async function agentSpeak(text,retried=false){if(!st.auth.authenticated||!text){agent(st.playing?'playing':(st.conversationOn?'listening':'idle'));scheduleConversationListen();return}const oldVol=audio.volume;try{if(st.playing)audio.volume=.22;const r=await fetch((cfg.apiBase||'api')+'/agent-voice.php',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json','X-CSRF-Token':st.auth.csrf||''},body:JSON.stringify({text})});if(!r.ok){if(r.status===403&&!retried){let j={};try{j=await r.clone().json()}catch(_){}if(j.error==='csrf_failed'){audio.volume=oldVol;await loadAuth(true);return agentSpeak(text,true)}}audio.volume=oldVol;scheduleConversationListen();return}const blob=await r.blob(),url=URL.createObjectURL(blob);if(st.voiceAudio)st.voiceAudio.pause();const a=new Audio(url);st.voiceAudio=a;await new Promise(resolve=>{a.onended=a.onerror=()=>{audio.volume=oldVol;URL.revokeObjectURL(url);resolve()};a.play().catch(()=>{audio.volume=oldVol;URL.revokeObjectURL(url);resolve()})});}catch(_){audio.volume=oldVol}finally{agent(st.playing?'playing':(st.conversationOn?'listening':'idle'));scheduleConversationListen()}}
  async function executeAgentAction(a){if(!a||!a.type||a.type==='none')return;const t=a.track_id?trackById(a.track_id):null;switch(a.type){case'play_track':if(t)play(t,0,'agent');break;case'pause_player':if(!audio.paused)audio.pause();break;case'next_track':stepTrack(1);break;case'previous_track':stepTrack(-1);break;case'open_view':navigate(a.view||'home');break;case'open_search':navigate('music',{q:a.query||''});break;case'open_library':navigate('library',{tab:a.tab||'all'});break;case'open_notifications':openNotificationDrawer();break;case'show_track':if(t){renderStory(t);setUrl('track',{id:t.id})}break;case'builder_add_track':if(t){const r=add(t,a.side||undefined);persist();navigate('builder');if(!r.ok)say(r.why==='already'?'That track is already on the build.':'That track will not fit on the requested side.')}break;case'builder_move_track':if(t&&a.side)moveBuilderTrackToSide(t.id,a.side);break;case'builder_fill':await fillBuild(a.side||'both');break;case'builder_dedupe':dedupeBuild();say('Removed duplicate tracks from the build.');break;case'builder_save':await saveBuilderDraft(false);break;case'create_playlist':{const j=await secureJsonPost('playlists.php',{action:'create',name:a.name||'Stonefellow Mix',description:'Curated by the Stonefellow agent.',visibility:a.visibility||'private',source_type:'agent',track_ids:Array.isArray(a.track_ids)?a.track_ids:[]});st.playlists={loaded:true,items:j.playlists||[]};navigate('playlist',{id:j.playlist.id});break}case'save_agent_session':{const j=await secureJsonPost('playlists.php',{action:'save_agent_session',name:a.name||'Agent Listening Session'});st.playlists={loaded:true,items:j.playlists||[]};navigate('playlist',{id:j.playlist.id});break}case'start_listening_session':{startAgentListeningSession(a.session);break}case'session_feedback':{if(a.session_id&&a.track_id){const x=await secureJsonPost('listening-sessions.php',{action:'feedback',session_id:a.session_id,track_id:a.track_id,sentiment:a.sentiment||'neutral'});st.agentSession={...st.agentSession,...(x.session||{})};await loadPersonalization(true);renderAgentSessionPanel()}break}case'end_listening_session':{if(a.session_id){const x=await secureJsonPost('listening-sessions.php',{action:'end',session_id:a.session_id});st.agentSession={...st.agentSession,...(x.session||{}),status:'ended'};clearPlaylistPlayback();renderAgentSessionPanel()}break}case'save_current_listening_session':{if(a.session_id){const x=await secureJsonPost('listening-sessions.php',{action:'save_playlist',session_id:a.session_id,name:a.name||st.agentSession.title||'Agent Listening Session'});st.playlists={loaded:true,items:x.playlists||[]};navigate('playlist',{id:x.playlist.id})}break}case'open_queue':{openQueue();break}case'queue_add_track':{if(t)await addTrackToQueue(t,'end');break}case'queue_play_next':{if(t)await addTrackToQueue(t,'next');break}case'queue_remove_track':{if(a.track_id)await removeTrackFromQueue(a.track_id);break}case'queue_clear':{await clearQueue(false);break}}}
  function syncAuthMenu(){
    // Account navigation is rendered exclusively by PHP on full-page requests.
    document.documentElement.dataset.authState=st.auth.authenticated?'logged-in':'logged-out';
  }
  async function loadAuth(force=false){
    if(st.auth.loaded&&!force)return st.auth;
    try{
      const r=await fetch((cfg.apiBase||'api')+'/auth.php',{cache:'no-store',credentials:'same-origin'});
      const j=await r.json();
      if(!r.ok||j.ok===false)throw new Error(j.message||j.error||'Could not load account status.');
      st.auth={loaded:true,authenticated:!!j.authenticated,user:j.user||null,csrf:j.csrf||null};
    }catch(e){
      st.auth={...st.auth,loaded:true,error:e.message};
    }
    syncAuthMenu();return st.auth;
  }
  async function authPost(body,retried=false){
    if(!st.auth.csrf)await loadAuth(true);
    const headers={'Content-Type':'application/json','X-CSRF-Token':st.auth.csrf||''};
    const r=await fetch((cfg.apiBase||'api')+'/auth.php',{method:'POST',headers,credentials:'same-origin',body:JSON.stringify(body||{})});
    let j={};try{j=await r.json()}catch(_){throw new Error('Account service returned an invalid response.')}
    if(r.status===403&&j.error==='csrf_failed'&&!retried){await loadAuth(true);return authPost(body,true)}
    if(!r.ok||j.ok===false){const e=new Error(j.message||j.error||'Account request failed.');e.payload=j;e.status=r.status;throw e}
    if(Object.prototype.hasOwnProperty.call(j,'authenticated')||j.user){
      const hasAuth=Object.prototype.hasOwnProperty.call(j,'authenticated');
      const authenticated=hasAuth?!!j.authenticated:(j.user?true:st.auth.authenticated);
      st.auth={loaded:true,authenticated,user:j.user||(authenticated?st.auth.user:null),csrf:j.csrf||st.auth.csrf||null};
      syncAuthMenu();
    }
    return j;
  }
  async function secureJsonPost(path,payload,retried=false){
    if(!st.auth.csrf)await loadAuth(true);
    const r=await fetch((cfg.apiBase||'api')+'/'+path,{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json','X-CSRF-Token':st.auth.csrf||''},body:JSON.stringify(payload||{})});
    let j={};try{j=await r.json()}catch(_){throw new Error('The server returned an invalid response.')}
    if(r.status===403&&j.error==='csrf_failed'&&!retried){await loadAuth(true);return secureJsonPost(path,payload,true)}
    if(!r.ok||j.ok===false){const e=new Error(j.message||j.error||'Request failed.');e.payload=j;e.status=r.status;throw e}
    return j;
  }
  function applyQueue(queue){const q=queue||{};st.queue.loaded=true;st.queue.items=Array.isArray(q.items)?q.items:[];updateQueueUi();return st.queue.items}
  function updateQueueUi(){const n=st.queue.items.length;if(playerQueueCount)playerQueueCount.textContent=String(n);if(queueDrawerCount)queueDrawerCount.textContent=n+' track'+(n===1?'':'s');if(st.queue.open)renderQueueDrawer()}
  async function loadQueue(force=false){if(!st.auth.authenticated){st.queue={...st.queue,loaded:true,items:[]};updateQueueUi();return st.queue.items}if(st.queue.loaded&&!force)return st.queue.items;try{const j=await api('queue.php');if(j.csrf)st.auth.csrf=j.csrf||st.auth.csrf;applyQueue(j.queue)}catch(_){st.queue={...st.queue,loaded:true,items:[]};updateQueueUi()}return st.queue.items}
  function pushQueueHistory(){const id=st.track?.id;if(!id)return;const h=Array.isArray(st.queue.history)?st.queue.history:[];if(h[0]!==id)h.unshift(id);st.queue.history=h.slice(0,30);localStorage.setItem('stonefellow.queue.history.v1',JSON.stringify(st.queue.history))}
  async function addTrackToQueue(t,placement='end'){if(!t)return;if(!st.auth.authenticated){say('Sign in to keep an Up Next queue across devices.',()=>navigate('login'));return}try{const j=await secureJsonPost('queue.php',{action:'add',track_id:t.id,placement:placement==='next'?'next':'end'});applyQueue(j.queue);say(placement==='next'?'“'+t.title+'” will play next.':'Added “'+t.title+'” to Up Next.')}catch(e){say(e.message)}}
  async function removeTrackFromQueue(trackId){if(!st.auth.authenticated)return;try{const j=await secureJsonPost('queue.php',{action:'remove',track_id:trackId});applyQueue(j.queue)}catch(e){say(e.message)}}
  async function removeQueueItem(itemId){try{const j=await secureJsonPost('queue.php',{action:'remove',item_id:Number(itemId)});applyQueue(j.queue)}catch(e){say(e.message)}}
  async function reorderQueueItem(itemId,delta){const ids=st.queue.items.map(x=>Number(x.item_id)),i=ids.indexOf(Number(itemId)),j=i+Number(delta);if(i<0||j<0||j>=ids.length)return;[ids[i],ids[j]]=[ids[j],ids[i]];try{const x=await secureJsonPost('queue.php',{action:'reorder',item_ids:ids});applyQueue(x.queue)}catch(e){say(e.message)}}
  async function clearQueue(confirmFirst=true){if(!st.auth.authenticated)return;if(confirmFirst&&!confirm('Clear everything from Up Next?'))return;try{const j=await secureJsonPost('queue.php',{action:'clear'});applyQueue(j.queue);if(!confirmFirst)say('Up Next is clear.')}catch(e){say(e.message)}}
  async function takeQueueItem(itemId){if(agentSessionActive()){say('End the active Agent listening session before switching to a queued track.');return false}try{const j=await secureJsonPost('queue.php',{action:'take',item_id:Number(itemId)});applyQueue(j.queue);const t=j.item?trackById(j.item.track_id):null;if(!t)return false;pushQueueHistory();play(t,0,'queue');return true}catch(e){say(e.message);return false}}
  async function playNextFromQueue(){if(agentSessionActive()||!st.auth.authenticated)return false;try{const j=await secureJsonPost('queue.php',{action:'pop'});applyQueue(j.queue);const t=j.item?trackById(j.item.track_id):null;if(!t)return false;pushQueueHistory();play(t,0,'queue');return true}catch(_){return false}}
  function renderQueueDrawer(){if(!queueContent)return;const rows=st.queue.items||[];queueContent.innerHTML=rows.length?rows.map((x,i)=>`<article class="queue-item"><button type="button" class="queue-item-play" data-queue-play="${x.item_id}" aria-label="Play ${esc(x.title)}">▶</button><div><strong>${esc(x.title)}</strong><small>${esc(x.release||'')} · ${time(x.duration)}</small></div><div class="queue-item-actions"><button type="button" data-queue-move="${x.item_id}" data-dir="-1" ${i===0?'disabled':''}>↑</button><button type="button" data-queue-move="${x.item_id}" data-dir="1" ${i===rows.length-1?'disabled':''}>↓</button><button type="button" data-queue-remove="${x.item_id}" aria-label="Remove ${esc(x.title)}">×</button></div></article>`).join(''):'<p class="drawer-empty">Your Up Next queue is empty.</p>';Array.from(queueContent.querySelectorAll('[data-queue-play]')).forEach(b=>b.onclick=()=>takeQueueItem(b.dataset.queuePlay));Array.from(queueContent.querySelectorAll('[data-queue-remove]')).forEach(b=>b.onclick=()=>removeQueueItem(b.dataset.queueRemove));Array.from(queueContent.querySelectorAll('[data-queue-move]')).forEach(b=>b.onclick=()=>reorderQueueItem(b.dataset.queueMove,b.dataset.dir));updateQueueUiCountOnly()}
  function updateQueueUiCountOnly(){const n=st.queue.items.length;if(playerQueueCount)playerQueueCount.textContent=String(n);if(queueDrawerCount)queueDrawerCount.textContent=n+' track'+(n===1?'':'s')}
  async function openQueue(){if(!st.auth.authenticated){say('Sign in to use a persistent Up Next queue.',()=>navigate('login'));return}await loadQueue(true);st.queue.open=true;if(queueDrawer)queueDrawer.hidden=false;if(queueBackdrop)queueBackdrop.hidden=false;playerQueueButton?.setAttribute('aria-expanded','true');document.body.classList.add('queue-open');renderQueueDrawer()}
  function closeQueue(){st.queue.open=false;if(queueDrawer)queueDrawer.hidden=true;if(queueBackdrop)queueBackdrop.hidden=true;playerQueueButton?.setAttribute('aria-expanded','false');document.body.classList.remove('queue-open')}
  async function loadPersonalization(force=false){
    if(!st.auth.authenticated){st.personalization={loaded:true,favorites:{tracks:[],releases:[]},continue_listening:[],history:[],recommendations:{personalized:false,summary:'Sign in and listen to make recommendations personal.',signals:{},items:[]}};return st.personalization}
    if(st.personalization.loaded&&!force)return st.personalization;
    try{const j=await api('personalization.php');st.personalization={loaded:true,...(j.personalization||{})};if(j.csrf)st.auth.csrf=j.csrf||st.auth.csrf}catch(_){st.personalization={loaded:true,favorites:{tracks:[],releases:[]},continue_listening:[],history:[]}}
    return st.personalization;
  }
